-- Canonical export recovered read-only from Staging migration history.
-- Version: 20260831070033; name: enterprise_esg_annual_summary

create or replace view public.enterprise_esg_annual_summary with (security_invoker=true) as select e.id as enterprise_id, coalesce(a.period_label,'未指定期間') as period_label, count(a.id)::int as report_ready_assets, count(distinct a.asset_type)::int as asset_categories, coalesce(sum(a.metric_value) filter (where a.metric_value is not null),0)::numeric as metric_value_total, array_remove(array_agg(distinct tag),null) as sdg_tags from public.enterprises e left join public.enterprise_esg_assets a on a.enterprise_id=e.id and a.status='approved' and a.report_ready=true left join lateral unnest(coalesce(a.sdg_tags,array[]::text[])) tag on true group by e.id,coalesce(a.period_label,'未指定期間'); create index if not exists idx_esg_assets_enterprise_period_ready on public.enterprise_esg_assets(enterprise_id,period_label,report_ready,status); create or replace function public.admin_mark_esg_report_ready(p_asset_id uuid,p_ready boolean,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); begin if v_actor is null or not exists(select 1 from public.admin_roles where user_id=v_actor and role_key in ('super_admin','admin','outcome_reviewer','enterprise_reviewer')) then raise exception 'insufficient_privilege'; end if; update public.enterprise_esg_assets set report_ready=p_ready,updated_at=now() where id=p_asset_id and status='approved'; if not found then raise exception 'approved_asset_required'; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer',case when p_ready then 'mark_esg_report_ready' else 'unmark_esg_report_ready' end,'enterprise_esg_asset',p_asset_id::text,p_note); end; $$; revoke all on function public.admin_mark_esg_report_ready(uuid,boolean,text) from public,anon; grant execute on function public.admin_mark_esg_report_ready(uuid,boolean,text) to authenticated;
